#include <llvm/IR/IRBuilder.h>
#include <llvm/IR/LLVMContext.h>
#include <llvm/IR/LegacyPassManager.h>
#include <llvm/IR/Module.h>
#include <llvm/IR/Verifier.h>
#include <llvm/MC/TargetRegistry.h>
#include <llvm/Support/TargetSelect.h>
#include <llvm/Target/TargetMachine.h>
#include <llvm/Target/TargetOptions.h>
#include <iostream>

int main(int argc, char **argv) {
  const char *triple = argv[1];
  llvm::LLVMContext ctx;
  auto mod = new llvm::Module("t", ctx);
  mod->setTargetTriple(triple);
  auto *ft = llvm::FunctionType::get(llvm::Type::getVoidTy(ctx), false);
  auto *f =
      llvm::Function::Create(ft, llvm::GlobalValue::ExternalLinkage, "ctor", *mod);
  auto *bb = llvm::BasicBlock::Create(ctx, "", f);
  llvm::IRBuilder<>(bb).CreateRetVoid();
  llvm::StructType *st = llvm::StructType::get(
      ctx, {llvm::Type::getInt32Ty(ctx), llvm::PointerType::getUnqual(ctx),
            llvm::PointerType::getUnqual(ctx)});
  llvm::Constant *elem = llvm::ConstantStruct::get(
      st, {llvm::ConstantInt::get(llvm::Type::getInt32Ty(ctx), 65535),
           f, llvm::ConstantPointerNull::get(
                  llvm::PointerType::getUnqual(ctx))});
  auto *arrTy = llvm::ArrayType::get(st, 1);
  auto *init = llvm::ConstantArray::get(arrTy, {elem});
  new llvm::GlobalVariable(*mod, arrTy, false,
                           llvm::GlobalValue::AppendingLinkage, init,
                           "llvm.global_ctors");

  std::string err;
  auto target = llvm::TargetRegistry::lookupTarget(triple, err);
  if (!target) { std::cerr << err << "\n"; return 1; }
  llvm::TargetOptions opt;
  auto rm = std::optional<llvm::Reloc::Model>(llvm::Reloc::Model::PIC_);
  auto *tm = target->createTargetMachine(triple, "generic", "", opt, rm);
  mod->setDataLayout(tm->createDataLayout());
  llvm::legacy::PassManager pass;
  llvm::raw_os_ostream dest(std::cout);
  if (tm->addPassesToEmitFile(pass, dest, nullptr,
                              llvm::CodeGenFileType::AssemblyFile)) {
    std::cerr << "no emit\n";
    return 1;
  }
  pass.run(*mod);
  return 0;
}

